script:
export const meta = {
  name: 'image-leak-harden',
  description: 'Harden the prompts of images that leaked a real brand/trademark in pixels, and delete the leaked files so they can be regenerated clean',
  phases: [{ title: 'Harden leak prompts' }],
}
const BASE = '/Users/dhiren/Downloads/Deccan/Adobe-Freelance-Leads'
const AUDIT = '/private/tmp/claude-501/-Users-dhiren-Downloads-Deccan/aa9e6dfc-7579-493e-a3a8-45be309ed406/scratchpad/audit_bytask.json'
const IDS = args
const SCHEMA = {
  type: 'object',
  properties: {
    task_id: { type: 'string' },
    hardened_files: { type: 'array', items: { type: 'string' } },
    deleted_files: { type: 'array', items: { type: 'string' } },
    image_files_to_regen: { type: 'array', items: { type: 'string' } },
    video_files_to_regen: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
  },
  required: ['task_id', 'hardened_files', 'deleted_files', 'summary'],
}
const results = await parallel(IDS.map((id) => () => agent(
  `Task ${id} has generated image/video assets that baked a REAL brand / logo / trademark / trade-dress / real-venue-signage / real-person-caption into the PIXELS (the audit caught them). Fix the PROMPTS so a regeneration comes out clean.\n\n` +
  `1. Read this task's audit entry: open ${AUDIT}, read the "${id}" entry's "leaked_files" array (and any note in it) — these are the exact files that leaked, sometimes with a description of WHAT leaked (e.g. "Marshall amplifier trade dress", "KATZ'S DELICATESSEN on the paper", a performer-name caption).\n` +
  `2. Read ${BASE}/input_assets_v3/${id}/asset_plan.json and find each leaked file's asset entry (match on filename; a leaked_files string may include a description after " - ", the filename is the leading part).\n` +
  `3. For EACH leaked asset, HARDEN its "prompt" in the asset_plan.json: append a strong, specific anti-brand clause naming what must NOT appear and what the surface should show instead — e.g. "CRITICAL: absolutely no real brand names, logos, wordmarks, trademarks or trade dress anywhere; the packaging/paper/amp/signage/apparel is plain and unbranded or carries ONLY the fictional brand <this task's brand name>; no famous-brand look-alikes (no Katz's-style deli paper, no Marshall-style amp livery, etc.); no burned-in real person names or captions." Keep the rest of the prompt and its engineered defect intact.\n` +
  `4. DELETE each leaked file from ${BASE}/input_assets_v3/${id}/assets/ (rm) so it will be regenerated fresh from the hardened prompt.\n` +
  `5. Report: hardened_files (asset filenames whose prompt you hardened), deleted_files (files you removed), image_files_to_regen (the .jpg/.png ones), video_files_to_regen (the .mp4/.mov ones), and a one-line summary. Edit ONLY this task's asset_plan.json and delete ONLY the leaked files.`,
  { agentType: 'general-purpose', phase: 'Harden leak prompts', label: `leak:${id}`, schema: SCHEMA }
)))
const r = results.filter(Boolean)
return {
  tasks: r.length,
  total_hardened: r.reduce((s, x) => s + (x.hardened_files || []).length, 0),
  image_regen: r.flatMap(x => (x.image_files_to_regen || []).map(f => x.task_id)),
  image_regen_tasks: [...new Set(r.filter(x => (x.image_files_to_regen||[]).length).map(x => x.task_id))],
  video_regen_tasks: [...new Set(r.filter(x => (x.video_files_to_regen||[]).length).map(x => x.task_id))],
  per_task: r.map(x => ({ id: x.task_id, hardened: x.hardened_files, deleted: (x.deleted_files||[]).length })),
}
